import{_ as a,c as t,a2 as i,o as n}from"./chunks/framework.YPpNXepj.js";const r="/images/experiments-example.png",d=JSON.parse('{"title":"Experiments","description":"","frontmatter":{},"headers":[],"relativePath":"experiments.md","filePath":"experiments.md"}'),o={name:"experiments.md"};function s(l,e,p,c,u,m){return n(),t("div",null,e[0]||(e[0]=[i('<h1 id="experiments" tabindex="-1">Experiments <a class="header-anchor" href="#experiments" aria-label="Permalink to &quot;Experiments&quot;">​</a></h1><p>Vanguard occasionally uses experiments to trial new features before their full release. This guide explains how you can participate in these experiments and help shape the future of Vanguard.</p><h2 id="accessing-experiments" tabindex="-1">Accessing Experiments <a class="header-anchor" href="#accessing-experiments" aria-label="Permalink to &quot;Accessing Experiments&quot;">​</a></h2><p>You can find and manage available experiments through your account settings:</p><ol><li>Navigate to your account settings.</li><li>Look for the &quot;Experiments&quot; page.</li></ol><h2 id="managing-experiments" tabindex="-1">Managing Experiments <a class="header-anchor" href="#managing-experiments" aria-label="Permalink to &quot;Managing Experiments&quot;">​</a></h2><p>The Experiments page provides an overview of all available experiments:</p><p><img src="'+r+'" alt="A screenshot of the experiments manager"></p><p>For each experiment, you can:</p><ol><li><strong>View Details</strong>: Click the &quot;View Details&quot; button to learn more about the experiment.</li><li><strong>Enable/Disable</strong>: Choose whether to participate in each experiment.</li></ol><h2 id="experiment-information" tabindex="-1">Experiment Information <a class="header-anchor" href="#experiment-information" aria-label="Permalink to &quot;Experiment Information&quot;">​</a></h2><p>When viewing an experiment&#39;s details, you&#39;ll find:</p><ul><li>A description of the new feature being tested</li><li>The area of the project it affects (e.g., UI/UX, performance)</li><li>Options to enable or disable the feature</li></ul><h2 id="user-control" tabindex="-1">User Control <a class="header-anchor" href="#user-control" aria-label="Permalink to &quot;User Control&quot;">​</a></h2><p>Unlike traditional A/B testing, Vanguard gives you full control over your participation:</p><ul><li>You can enable or disable any available experiment at any time.</li><li>All experiments are opt-in, allowing you to try new features at your own pace.</li></ul><h2 id="feedback" tabindex="-1">Feedback <a class="header-anchor" href="#feedback" aria-label="Permalink to &quot;Feedback&quot;">​</a></h2><p>Your feedback on experiments is invaluable:</p><ul><li>While using experimental features, pay attention to your experience.</li><li>Use the provided feedback channels to share your thoughts, suggestions, or report any issues.</li></ul><p>By participating in experiments, you play a crucial role in Vanguard&#39;s development, helping to refine and improve features before their official release.</p>',20)]))}const x=a(o,[["render",s]]);export{d as __pageData,x as default};
